pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Ensure at least one recipient
        vm.assume(_tos.length > 0);

        // Capture the return value
        bool result;
        // If any call would revert, the reference contract reverts, so the result is never true
        // To distinguish between revert and false return, we wrap in try/catch
        try c.transfer(from, caddress, _tos, v) {
            result = true;
        } catch {
            result = false;
        }

        // Now compute whether all calls would succeed in isolation
        bool allSucceed = true;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            if (!success) {
                allSucceed = false;
                break;
            }
        }

        // Rule: result (transfer returning true) is equivalent to all individual calls succeeding
        assertTrue(result == allSucceed);
    }
}

